    long long w;
} Edge;

typedef struct {
    int parent;
    int rank;
} DSU;

int cmp_edges(const void *a, const void *b) {
    long long wa = ((const Edge *)a)->w;
    long long wb = ((const Edge *)b)->w;
    if (wa < wb) return -1;
    if (wa > wb) return 1;
    return 0;
}

int find_set(DSU *dsu, int x) {
    if (dsu[x].parent != x)
        dsu[x].parent = find_set(dsu, dsu[x].parent);
    return dsu[x].parent;
}

int union_set(DSU *dsu, int a, int b) {
    a = find_set(dsu, a);
    b = find_set(dsu, b);
    if (a == b) return 0;

    if (dsu[a].rank < dsu[b].rank) {
        dsu[a].parent = b;
    } else if (dsu[a].rank > dsu[b].rank) {
        dsu[b].parent = a;
    } else {
        dsu[b].parent = a;
        dsu[a].rank++;
    }
    return 1;
}

